<template>
  <view class="shell" :style="brandStyle">
    <view class="masthead"><view><text class="brand-name">{{ site?.brand.name || '客户应用' }}</text><text class="subject">{{ site?.tradingSubject || '正在读取应用登记' }}</text></view><button v-if="context" class="quiet" :disabled="busy" @click="logout">退出账号</button></view>
    <view v-if="error" class="feedback error" role="alert">{{ error }}</view><view v-if="notice" class="feedback" role="status">{{ notice }}</view>
    <view v-if="!site" class="entry"><text class="heading">连接你的机构</text><text class="muted">{{ busy ? '正在读取应用配置…' : '请重试读取应用登记，或联系维护人员核对开通状态。' }}</text><button :disabled="busy" @click="boot">重新连接</button></view>
    <view v-else-if="!context" class="entry">
      <text class="heading">{{ registering ? '建立本机构账号' : '欢迎回来' }}</text><text class="muted">使用本机构的独立账号。注册无需绑定手机号。</text>
      <label>用户名<input v-model="auth.username" placeholder="3—64位字母、数字、短横线或下划线" autocomplete="username" /></label>
      <label>密码<input v-model="auth.password" password placeholder="至少12个字符" :maxlength="72" /></label><label v-if="registering">昵称<input v-model="auth.nickname" maxlength="60" /></label>
      <button class="primary" :disabled="busy" @click="signIn">{{ busy ? '正在核验…' : registering ? '注册并进入' : '登录' }}</button><button class="quiet" :disabled="busy" @click="registering = !registering">{{ registering ? '已有账号，去登录' : '创建独立账号' }}</button>
    </view>
    <view v-else class="workspace">
      <view class="rail"><text class="account">{{ roleLabel }}</text><button v-for="item in tabs" :key="item.key" :class="{current:tab===item.key}" @click="switchTab(item.key)">{{ item.label }}</button><text v-if="site.operatingStatus==='EXPIRED_RESTRICTED'" class="status">合同已到期，可查看历史及导出</text></view>
      <view class="main">
        <view class="section-head"><text class="heading">{{ tabs.find(item=>item.key===tab)?.label }}</text><button class="quiet" :disabled="busy" @click="reload">刷新记录</button></view>
        <template v-if="tab==='catalog'">
          <view class="filters"><button v-for="item in allowedKinds" :key="item.kind" :class="{selected:kind===item.kind}" @click="loadKind(item.kind)">{{ item.label }}</button></view>
          <text v-if="!resources.length" class="empty">这里尚未发布{{ kindLabels[kind] }}，请稍后刷新。</text>
          <view v-for="row in resources" :key="row.id" class="resource" @click="openResource(row)"><image v-if="images[row.id]" :src="images[row.id]" mode="aspectFill" class="cover" /><view class="resource-copy"><text class="title">{{ row.title || row.name }}</text><text class="muted">{{ row.intro || row.persona || '查看详情' }}</text><text v-if="row.price !== undefined" class="price">{{ Number(row.price)===0 ? '免费' : '¥'+row.price }}</text></view><button class="quiet" @click.stop="openResource(row)">查看</button></view>
          <button v-if="resourceCursor" :disabled="busy" @click="loadMoreResources">读取下一页目录</button><view v-if="selected" class="detail">
            <view class="section-head"><text class="title">{{ selected.title || selected.name }}</text><button class="quiet" @click="selected=undefined">收起</button></view><text class="body-copy">{{ selected.detail || selected.intro || selected.persona }}</text>
            <template v-if="kind==='product'"><label>购买数量<input v-model="quantity" type="number" /></label><text class="muted">{{ context.paymentReady ? '以订单实际报价为准' : '支付尚未开通，当前可建立待支付订单。' }}</text><label>收货地址<picker :range="addresses.map(a=>String(a.name)+' '+String(a.detail))" :value="addressIndex" @change="addressIndex=Number($event.detail.value)"><view class="pick">{{ addresses[addressIndex] ? addresses[addressIndex].name+' '+addresses[addressIndex].detail : '先在“我的订单”中添加收货地址' }}</view></picker></label><button class="primary" :disabled="busy||!addresses.length" @click="placeOrder('product')">建立订单</button></template>
            <template v-if="kind==='course'"><button :disabled="busy" @click="placeOrder('course')">{{ Number(selected.price)===0 ? '免费订阅' : '建立课程订单' }}</button><text v-if="!context.paymentReady && Number(selected.price)>0" class="muted">支付未开通，付费章节须有真实有效的历史购买权益。</text><view v-for="row in chapters" :key="row.id" class="row"><text>{{ row.title }}{{ row.accessible ? '' : '（尚无学习权益）' }}</text><button :disabled="!row.accessible||busy" @click="readChapter(row)">阅读</button></view><view v-if="chapter" class="reading"><text class="title">{{ chapter.title }}</text><text class="body-copy">{{ chapter.content }}</text><button :disabled="busy" @click="saveProgress">标记已学完</button><text v-for="progress in progresses" :key="String(progress.chapterId)" class="muted">{{ progress.chapterId===chapter.id ? '本章已记录进度：'+progress.progress+'%' : '' }}</text></view></template>
            <template v-if="kind==='circle'"><text class="muted">{{ circleInfo?.member ? '已加入本圈' : '加入后可阅读帖子和参与交流' }}</text><view class="actions"><button :disabled="busy" @click="circleAction('join')">申请加入</button><button :disabled="busy" @click="circleAction('leave')">退出圈子</button><button :disabled="busy" @click="loadPosts(false)">读取帖子</button><button v-if="isAdmin" :disabled="busy" @click="loadPosts(true)">审核队列</button></view><label>帖子标题<input v-model="postForm.title" maxlength="120" /></label><label>正文<textarea v-model="postForm.content" maxlength="12000" /></label><view class="actions"><button :disabled="busy" @click="savePost(true)">保存草稿</button><button :disabled="busy" @click="savePost(false)">提交审核</button></view><view v-for="row in posts" :key="row.id" class="post"><text class="title">{{ row.title || '帖子' }}</text><text class="body-copy">{{ row.content }}</text><text class="muted">{{ stateLabel(row.status) }}</text><view class="actions"><button v-if="row.userId===context.userId" :disabled="busy" @click="editPost(row)">编辑</button><button v-if="isAdmin && row.status!=='DRAFT'" :disabled="busy" @click="reviewPost(row,'PUBLISHED')">审核发布</button><button v-if="isAdmin && row.status!=='DRAFT'" :disabled="busy" @click="reviewPost(row,'HIDDEN')">隐藏</button></view></view><button v-if="postCursor" :disabled="busy" @click="loadPosts(moderation,true)">读取下一页帖子</button><template v-if="isAdmin"><label>审核或禁言依据<input v-model="reviewReason" maxlength="500" /></label><button :disabled="busy" @click="loadCircleAdmin()">读取申请与成员</button><view v-for="row in joinRequests" :key="row.id" class="row"><text>申请人：{{ row.userId }}（{{ stateLabel(row.status) }}）</text><button v-if="row.status==='PENDING'" @click="reviewJoin(row,'APPROVED')">同意</button><button v-if="row.status==='PENDING'" @click="reviewJoin(row,'REJECTED')">拒绝</button></view><button v-if="joinCursor" :disabled="busy" @click="loadCircleAdmin('requests',true)">读取下一页申请</button><label>禁言分钟数（零为解除）<input v-model="muteMinutes" type="number" /></label><view v-for="row in members" :key="row.id" class="row"><text>{{ row.userId }}（{{ row.role }}）</text><button :disabled="busy" @click="mute(row)">设置禁言</button></view><button v-if="memberCursor" :disabled="busy" @click="loadCircleAdmin('members',true)">读取下一页成员</button></template></template>
            <template v-if="kind==='agent'"><text class="muted">{{ context.chatReady ? '本应用文字会话已开通' : '模型会话尚未开通，可查看既有会话。' }}</text><button :disabled="busy" @click="createChat">建立本角色会话</button></template>
          </view>
        </template>
        <template v-if="tab==='orders'"><text class="muted">交易与售后由{{ context.tradingSubject }}负责。</text><text v-if="!orders.length" class="empty">还没有订单，可先从目录选择商品或课程。</text><view v-for="row in orders" :key="row.id" class="record"><text class="title">订单 {{ row.id }}</text><text>{{ stateLabel(row.status) }}　¥{{ row.amount }}</text><button v-if="row.status==='PENDING'" :disabled="busy" @click="cancelOrder(row)">取消待支付订单</button><template v-if="['PAID','SHIPPED','COMPLETED','REFUNDED'].includes(String(row.status))"><label>售后原因<input v-model="aftercareReason" maxlength="500" /></label><button :disabled="busy" @click="aftercare(row)">提交售后申请</button></template></view><button v-if="orderCursor" :disabled="busy" @click="loadOrders(true)">读取下一页订单</button><template v-if="site.modules.includes('shop')"><text class="subheading">收货地址</text><view v-for="row in addresses" :key="row.id" class="row"><text>{{ row.name }}　{{ row.detail }}</text><button @click="editAddress(row)">编辑</button></view><label v-for="field in addressFields" :key="field.key">{{ field.label }}<input v-model="addressForm[field.key]" :maxlength="field.key==='detail'?300:60" /></label><label class="check"><switch :checked="addressForm.isDefault" @change="addressForm.isDefault=checkedEvent($event)" />默认地址</label><button :disabled="busy" @click="saveAddress">{{ addressForm.id ? '保存地址修改' : '添加收货地址' }}</button></template></template>
        <template v-if="tab==='chats'"><text v-if="!chats.length" class="empty">从目录选择智能体，建立属于你的会话。</text><view v-for="row in chats" :key="row.id" class="row"><text>{{ row.createdAt }}　会话 {{ row.id }}</text><button @click="openChat(row)">打开</button></view><button v-if="chatCursor" @click="loadChats(true)">读取下一页会话</button><view v-if="chat" class="detail"><view v-for="row in messages" :key="row.id" class="message"><text class="speaker">你</text><text class="body-copy">{{ row.userText }}</text><template v-if="row.assistantText"><text class="speaker">助手</text><text class="body-copy">{{ row.assistantText }}</text></template><text v-else class="muted">{{ row.state==='UNKNOWN' || row.state==='DISPATCHING' ? '结果尚未确认，请核对已有请求；系统不会自动再次调用。' : stateLabel(row.state) }}</text></view><button v-if="messageCursor" @click="loadMessages(true)">读取下一页消息</button><label>发送消息<textarea v-model="chatText" maxlength="2000" /></label><button class="primary" :disabled="busy||!context.chatReady" @click="sendMessage">{{ context.chatReady ? '发送' : '会话服务尚未开通' }}</button><button :disabled="busy" @click="loadMessages()">核对请求结果</button></view></template>
        <template v-if="tab==='manage'"><view class="filters"><button v-for="item in allowedKinds" :key="item.kind" @click="loadManage(item.kind)">{{ item.label }}</button></view><text class="muted">新增或编辑后需人工审核。只管理本应用自建内容，合同限额以服务端核验为准。</text><view v-for="row in managedRows" :key="row.id" class="row"><view><text>{{ row.title || row.name }}</text><text class="muted">{{ stateLabel(row.status || row.auditStatus) }}　修订 {{ row.revision }}</text></view><button @click="editContent(row)">编辑与审核</button></view><button v-if="manageCursor" @click="loadManage(manageKind,true)">读取下一页内容</button><button class="quiet" @click="newContent">新增{{ kindLabels[manageKind] }}</button><view class="detail"><text class="subheading">{{ contentForm.id ? '编辑内容' : '新建内容' }}</text><label>名称<input v-model="contentForm.title" maxlength="120" /></label><label v-if="manageKind!=='agent'">简介<textarea v-model="contentForm.intro" maxlength="1000" /></label><label v-if="manageKind==='product'">商品正文<textarea v-model="contentForm.detail" maxlength="12000" /></label><template v-if="manageKind==='product'||manageKind==='course'"><label>价格（元）<input v-model="contentForm.price" type="digit" /></label><label v-if="manageKind==='product'">库存<input v-model="contentForm.stock" type="number" /></label><label v-else>权益有效天数（零为不限制）<input v-model="contentForm.validityDays" type="number" /></label><button :disabled="busy" @click="chooseAsset">上传PNG/JPEG封面</button><text v-if="contentForm.assetIds.length" class="muted">已选择 {{ contentForm.assetIds.length }} 个本应用附件</text></template><template v-if="manageKind==='agent'"><label>公开角色说明<textarea v-model="contentForm.persona" maxlength="2000" /></label><label v-if="!contentForm.id && site.templateId!=='single-agent'">所属圈子<picker :range="ownCircles.map(row=>String(row.name))" :value="contentCircleIndex" @change="contentCircleIndex=Number($event.detail.value)"><view class="pick">{{ ownCircles[contentCircleIndex]?.name || '先创建并启用本应用圈子' }}</view></picker><button v-if="ownCircleCursor" :disabled="busy" @click="loadOwnCircles">读取下一页圈子</button></label></template><button class="primary" :disabled="busy||manageKind==='circle'&&!!contentForm.id" @click="saveContent">{{ contentForm.id ? '保存修改并重新审核' : '创建待审核内容' }}</button><template v-if="contentForm.id"><label>审核依据<input v-model="reviewReason" maxlength="500" /></label><label v-if="manageKind==='circle'" class="check"><switch :checked="contentForm.needApproval" @change="contentForm.needApproval=checkedEvent($event)" />加入需审核</label><view class="actions"><button :disabled="busy" @click="publishContent(true)">审核后启用</button><button :disabled="busy" @click="publishContent(false)">暂停发布</button></view><template v-if="manageKind==='course'"><text class="subheading">课程章节</text><view v-for="row in adminChapters" :key="row.id" class="row"><text>{{ row.title }}</text><button @click="editChapter(row)">编辑</button></view><label>章节标题<input v-model="chapterForm.title" maxlength="120" /></label><label>章节正文<textarea v-model="chapterForm.content" maxlength="30000" /></label><label>排序<input v-model="chapterForm.sortOrder" type="number" /></label><label class="check"><switch :checked="chapterForm.freeTrial" @change="chapterForm.freeTrial=checkedEvent($event)" />允许试看</label><button :disabled="busy" @click="saveChapter">保存章节并重新审核</button><button class="quiet" @click="resetChapter">新增另一个章节</button></template></template></view></template>
        <template v-if="tab==='account'"><text class="title">本机构账号 {{ context.userId }}</text><text class="muted">密码修改会撤销其他登录会话，请重新登录。</text><label>当前密码<input v-model="passwordForm.currentPassword" password /></label><label>新密码<input v-model="passwordForm.newPassword" password /></label><button :disabled="busy" @click="changePassword">修改密码</button><template v-if="isAdmin"><text class="subheading">客户数据退出</text><text class="muted">导出本客户各应用的内容、订单、学习、圈子、会话和本地附件。认证凭据不导出，用户手机号脱敏。冻结期间可下载已有快照。</text><button :disabled="busy" @click="createExport">建立分页退出快照</button><view v-if="exported"><button :disabled="busy" @click="downloadManifest">保存退出总清单</button><text>{{ exported.manifest.totalRows }}条记录　{{ exported.manifest.totalBytes }}字节</text><text class="muted">下载授权截止：{{ exported.expiresAt }}</text><view v-for="(collection,name) in exported.manifest.collections" :key="name" class="record"><text>{{ collectionLabels[String(name)] || name }}：{{ collection.rows }}条</text><button v-for="page in collection.pages" :key="page.page" :disabled="busy" @click="downloadPage(String(name),page.page)">保存第 {{ page.page+1 }} 页</button></view></view></template></template>
      </view>
    </view>
    <view class="footer"><text>应用登记主体：{{ site?.applicationSubject || '待读取' }}</text><text>交易与服务：{{ site?.tradingSubject || '待读取' }}</text></view>
  </view>
</template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import {managedBootstrap,managedCall,managedLogin,managedLogout,managedAsset,hasManagedSession,clearManagedSession,requestKey,ManagedClientError,type ManagedPublic,type ManagedContext,type ManagedRow,type ManagedKind} from '../client'
import {readManagedImage,saveManagedJson} from '../files'
type Page={items:ManagedRow[];nextCursor?:string|null;nextSequence?:number|null}
type ExportInfo={id:string;downloadToken:string;expiresAt:string;manifest:{totalRows:number;totalBytes:number;collections:Record<string,{rows:number;pages:Array<{page:number;sha256:string}>}>}}
const site=ref<ManagedPublic>(),context=ref<ManagedContext>(),busy=ref(false),error=ref(''),notice=ref(''),registering=ref(false),tab=ref('catalog'),kind=ref<ManagedKind>('product'),manageKind=ref<ManagedKind>('product')
const resourceCursor=ref('')
const auth=reactive({username:'',password:'',nickname:''}),resources=ref<ManagedRow[]>([]),images=reactive<Record<string,string>>({}),selected=ref<ManagedRow>(),orders=ref<ManagedRow[]>([]),addresses=ref<ManagedRow[]>([]),chapters=ref<ManagedRow[]>([]),chapter=ref<ManagedRow>(),progresses=ref<ManagedRow[]>([]),quantity=ref('1'),addressIndex=ref(0)
const posts=ref<ManagedRow[]>([]),circleInfo=ref<ManagedRow>(),joinRequests=ref<ManagedRow[]>([]),members=ref<ManagedRow[]>([]),memberCursor=ref(''),joinCursor=ref(''),ownCircleCursor=ref(''),postCursor=ref(''),moderation=ref(false),orderCursor=ref(''),reviewReason=ref(''),muteMinutes=ref('0'),aftercareReason=ref('')
const postForm=reactive({id:'',title:'',content:'',updatedAt:'',requestKey:requestKey()}),aftercareKeys:Record<string,string>={},orderKey=ref(requestKey())
const chats=ref<ManagedRow[]>([]),chat=ref<ManagedRow>(),messages=ref<ManagedRow[]>([]),chatCursor=ref(''),messageCursor=ref<number|null>(null),chatText=ref(''),chatRequestKey=ref(requestKey())
const managedRows=ref<ManagedRow[]>([]),manageCursor=ref(''),ownCircles=ref<ManagedRow[]>([]),contentCircleIndex=ref(0),adminChapters=ref<ManagedRow[]>([])
const contentDefaults=()=>({id:'',revision:1,title:'',intro:'',detail:'',price:'0',stock:'0',validityDays:'0',persona:'',assetIds:[] as string[],needApproval:false})
const contentForm=reactive(contentDefaults()),chapterForm=reactive({id:'',title:'',content:'',sortOrder:'0',freeTrial:false}),passwordForm=reactive({currentPassword:'',newPassword:''}),exported=ref<ExportInfo>()
const addressFields=[{key:'name',label:'收货人'},{key:'phone',label:'收货电话'},{key:'province',label:'省份'},{key:'city',label:'城市'},{key:'district',label:'区县'},{key:'detail',label:'详细地址'}] as const
const addressForm=reactive({id:'',name:'',phone:'',province:'',city:'',district:'',detail:'',isDefault:false})
const kindLabels:Record<ManagedKind,string>={product:'商品',course:'课程',circle:'圈子',agent:'智能体'}
const allowedKinds=computed(()=>Object.entries(kindLabels).filter(([key])=>(site.value?.templateId!=='single-agent'||key==='agent')&&site.value?.modules.includes(({product:'shop',course:'course',circle:'circle',agent:'agent'} as Record<string,string>)[key])).map(([kind,label])=>({kind:kind as ManagedKind,label})))
const isAdmin=computed(()=>context.value?.role==='CUSTOMER_ADMIN'),roleLabel=computed(()=>isAdmin.value?'客户管理员':context.value?.role==='CUSTOMER_SUPPORT'?'客户客服':'本机构成员')
const brandStyle=computed(()=>{const color=/^#[a-f0-9]{6}$/i.test(site.value?.brand.themeColor||'')?site.value!.brand.themeColor:'#287287';const rgb=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);const luminance=.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];return {'--brand':color,'--brand-ink':luminance>.179?'#152b3d':'#ffffff','--accent-ink':luminance>.4?'#21354a':color}})
const tabs=computed(()=>[{key:'catalog',label:site.value?.templateId==='single-agent'?'本机构助手':'本机构目录'},{key:'orders',label:'我的订单'},...(site.value?.modules.includes('agent')?[{key:'chats',label:'我的会话'}]:[]),...(isAdmin.value?[{key:'manage',label:'内容经营'}]:[]),{key:'account',label:'账号与数据'}])
const collectionLabels:Record<string,string>={users:'用户',products:'商品',courses:'课程',chapters:'章节',progress:'学习进度',circles:'圈子',members:'成员',posts:'帖子',agents:'智能体',addresses:'收货地址',orders:'订单',knowledge:'圈知识',assets:'本地附件',origins:'内容来源',orderOrigins:'订单来源',postOrigins:'帖子来源',joinRequests:'入圈申请',mutes:'禁言记录',chatSessions:'会话',chatMessages:'会话消息',aftercare:'售后',audit:'操作审计'}
function checkedEvent(event:unknown){return !!(event as {detail?:{value?:boolean}}).detail?.value}
function stateLabel(value:unknown){return ({PENDING:'待处理',ON_SALE:'已上架',OFF_SHELF:'已下架',APPROVED:'已审核',DRAFT:'草稿',AUDITING:'待审核',PUBLISHED:'已发布',HIDDEN:'已隐藏',ACTIVE:'有效',DISABLED:'已暂停',PAID:'已支付',SHIPPED:'已发货',COMPLETED:'已完成',CANCELLED:'已取消',REFUNDED:'已退款',REJECTED:'已拒绝',ABORTED:'请求已终止',UNKNOWN:'结果未知',DISPATCHING:'等待结果'} as Record<string,string>)[String(value)]||String(value||'')}
async function perform(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作未完成，请核对已有记录';if(e instanceof ManagedClientError&&e.status===401){context.value=undefined;selected.value=undefined;exported.value=undefined;resources.value=[];orders.value=[];chats.value=[];messages.value=[]}}finally{busy.value=false}}
async function boot(){await perform(async()=>{site.value=await managedBootstrap();if(hasManagedSession()){context.value=await managedCall('/context');await reloadData()}})}
async function signIn(){await perform(async()=>{await managedLogin(auth.username,auth.password,registering.value?auth.nickname:undefined);auth.password='';context.value=await managedCall('/context');await reloadData()})}
async function logout(){await perform(async()=>{await managedLogout();context.value=undefined;selected.value=undefined;exported.value=undefined;resources.value=[];orders.value=[];chats.value=[];messages.value=[];notice.value='已退出本机构账号'})}
async function reloadData(){if(!context.value)return;context.value=await managedCall('/context');site.value={...site.value!,...context.value};if(tab.value==='catalog'){if(!allowedKinds.value.some(row=>row.kind===kind.value))kind.value=allowedKinds.value[0]?.kind||'agent';await resourcesData()}else if(tab.value==='orders'){await ordersData();if(site.value?.modules.includes('shop'))addresses.value=await managedCall('/addresses')}else if(tab.value==='chats')await chatsData();else if(tab.value==='manage')await manageData()}
const loadMoreResources=()=>perform(()=>resourcesData(true))
const reload=()=>perform(reloadData)
async function switchTab(value:string){tab.value=value;selected.value=undefined;await reload()}
async function resourcesData(more=false){if(!allowedKinds.value.some(row=>row.kind===kind.value)){resources.value=[];return}const page=await managedCall<Page>('/resources/paged?kind='+kind.value+(more&&resourceCursor.value?'&cursor='+encodeURIComponent(resourceCursor.value):''));resources.value=more?[...resources.value,...page.items]:page.items;resourceCursor.value=page.nextCursor||'';for(const row of page.items){const path=Array.isArray(row.images)?row.images[0]:row.cover;if(typeof path==='string'&&/^\/api\/v1\/lease\/assets\/[a-zA-Z0-9_-]+$/.test(path)){try{images[row.id]=await managedAsset(path.split('/').at(-1)!)}catch{delete images[row.id]}}}}
async function loadKind(value:ManagedKind){kind.value=value;selected.value=undefined;await perform(()=>resourcesData())}
async function openResource(row:ManagedRow){await perform(async()=>{selected.value=row;chapter.value=undefined;posts.value=[];postCursor.value='';orderKey.value=requestKey();if(kind.value==='product')addresses.value=await managedCall('/addresses');if(kind.value==='course'){chapters.value=await managedCall('/courses/'+row.id+'/chapters');progresses.value=await managedCall('/courses/'+row.id+'/progress')}if(kind.value==='circle'){circleInfo.value=await managedCall('/circles/'+row.id);Object.assign(postForm,{id:'',title:'',content:'',updatedAt:'',requestKey:requestKey()})}})}
async function placeOrder(type:'product'|'course'){await perform(async()=>{if(!selected.value)return;const result=await managedCall<ManagedRow>('/orders/'+(type==='product'?'products':'courses'),'POST',type==='product'?{productId:selected.value.id,quantity:Number(quantity.value),addressId:addresses.value[addressIndex.value]?.id,requestKey:orderKey.value}:{courseId:selected.value.id,requestKey:orderKey.value});notice.value='订单已建立：'+stateLabel(result.status)+'，金额以订单记录为准';orderKey.value=requestKey()})}
async function readChapter(row:ManagedRow){await perform(async()=>{chapter.value=await managedCall('/courses/'+selected.value!.id+'/chapters/'+row.id)})}
async function saveProgress(){await perform(async()=>{await managedCall('/courses/'+selected.value!.id+'/chapters/'+chapter.value!.id+'/progress','PUT',{progress:100});progresses.value=await managedCall('/courses/'+selected.value!.id+'/progress');notice.value='学习进度已保存'})}
async function circleAction(action:'join'|'leave'){await perform(async()=>{const result=await managedCall<ManagedRow>('/circles/'+selected.value!.id+'/'+action,'POST',{});circleInfo.value=await managedCall('/circles/'+selected.value!.id);notice.value='圈子操作已处理：'+stateLabel(result.status)})}
async function postsData(admin:boolean,more=false){const page=await managedCall<Page>('/circles/'+selected.value!.id+'/'+(admin?'moderation':'posts')+(more&&postCursor.value?'?cursor='+encodeURIComponent(postCursor.value):''));posts.value=more?[...posts.value,...page.items]:page.items;postCursor.value=page.nextCursor||'';moderation.value=admin}
const loadPosts=(admin:boolean,more=false)=>perform(()=>postsData(admin,more))
function editPost(row:ManagedRow){Object.assign(postForm,{id:row.id,title:row.title,content:row.content,updatedAt:row.updatedAt})}
async function savePost(draft:boolean){await perform(async()=>{const path='/circles/'+selected.value!.id+'/posts';await managedCall(path+(postForm.id?'/'+postForm.id:''),postForm.id?'PUT':'POST',{title:postForm.title,content:postForm.content,draft,...(postForm.id?{updatedAt:postForm.updatedAt}:{requestKey:postForm.requestKey})});Object.assign(postForm,{id:'',title:'',content:'',updatedAt:'',requestKey:requestKey()});await postsData(moderation.value);notice.value=draft?'草稿已保存':'已提交审核'})}
async function reviewPost(row:ManagedRow,status:string){await perform(async()=>{await managedCall('/circles/'+selected.value!.id+'/posts/'+row.id+'/review','POST',{status,reason:reviewReason.value,updatedAt:row.updatedAt});await postsData(true)})}
async function circleAdminData(target:'requests'|'members',more=false){const cursor=target==='requests'?joinCursor:memberCursor,rows=target==='requests'?joinRequests:members;const page=await managedCall<Page>('/circles/'+selected.value!.id+'/'+target+(more&&cursor.value?'?cursor='+encodeURIComponent(cursor.value):''));rows.value=more?[...rows.value,...page.items]:page.items;cursor.value=page.nextCursor||''}
async function loadCircleAdmin(target?:'requests'|'members',more=false){await perform(async()=>{if(target)await circleAdminData(target,more);else {await circleAdminData('requests');await circleAdminData('members')}})}
async function reviewJoin(row:ManagedRow,status:string){await perform(async()=>{await managedCall('/circles/'+selected.value!.id+'/requests/'+row.id+'/review','POST',{status,reason:reviewReason.value});await circleAdminData('requests');await circleAdminData('members')})}
async function mute(row:ManagedRow){await perform(async()=>{await managedCall('/circles/'+selected.value!.id+'/members/'+row.userId+'/mute','POST',{minutes:Number(muteMinutes.value),reason:reviewReason.value});notice.value=Number(muteMinutes.value)===0?'已解除禁言':'已设置本圈禁言'})}
async function ordersData(more=false){const page=await managedCall<Page>('/orders'+(more&&orderCursor.value?'?cursor='+orderCursor.value:''));orders.value=more?[...orders.value,...page.items]:page.items;orderCursor.value=page.nextCursor||''}
const loadOrders=(more=false)=>perform(()=>ordersData(more))
async function cancelOrder(row:ManagedRow){await perform(async()=>{await managedCall('/orders/'+row.id+'/cancel','POST',{});await ordersData();notice.value='待支付订单已取消'})}
async function aftercare(row:ManagedRow){await perform(async()=>{aftercareKeys[row.id]??=requestKey();await managedCall('/aftercare','POST',{orderId:row.id,reason:aftercareReason.value,requestKey:aftercareKeys[row.id]});notice.value='售后申请已登记，等待服务方处理'})}
function editAddress(row:ManagedRow){Object.assign(addressForm,row)}
async function saveAddress(){await perform(async()=>{const {id,...body}=addressForm;await managedCall('/addresses'+(id?'/'+id:''),id?'PUT':'POST',body);addresses.value=await managedCall('/addresses');addressForm.id='';notice.value='收货地址已保存'})}
async function chatsData(more=false){const page=await managedCall<Page>('/chats'+(more&&chatCursor.value?'?cursor='+chatCursor.value:''));chats.value=more?[...chats.value,...page.items]:page.items;chatCursor.value=page.nextCursor||''}
const loadChats=(more=false)=>perform(()=>chatsData(more))
async function createChat(){await perform(async()=>{chat.value=await managedCall('/chats','POST',{agentId:selected.value!.id});tab.value='chats';await chatsData();await messagesData();notice.value='会话已建立'})}
async function openChat(row:ManagedRow){await perform(async()=>{chat.value=row;chatRequestKey.value=requestKey();await messagesData()})}
async function messagesData(more=false){const page=await managedCall<Page>('/chats/'+chat.value!.id+'/messages'+(more&&messageCursor.value?'?after='+messageCursor.value:''));messages.value=more?[...messages.value,...page.items]:page.items;messageCursor.value=page.nextSequence||null}
const loadMessages=(more=false)=>perform(()=>messagesData(more))
async function sendMessage(){await perform(async()=>{const result=await managedCall<ManagedRow>('/chats/'+chat.value!.id+'/messages','POST',{text:chatText.value,requestKey:chatRequestKey.value});await messagesData();if(result.state==='COMPLETED'){chatText.value='';chatRequestKey.value=requestKey()}else notice.value='已有请求结果尚未确认，请核对会话记录，保留原请求标识'})}
async function manageData(more=false){if(!allowedKinds.value.some(row=>row.kind===manageKind.value))manageKind.value=allowedKinds.value[0]?.kind||'agent';const page=await managedCall<Page>('/manage/'+manageKind.value+(more&&manageCursor.value?'?cursor='+manageCursor.value:''));managedRows.value=more?[...managedRows.value,...page.items]:page.items;manageCursor.value=page.nextCursor||'';if(manageKind.value==='agent'&&site.value?.templateId!=='single-agent')await ownCirclesData()}
async function ownCirclesData(more=false){const page=await managedCall<Page>('/manage/circle'+(more&&ownCircleCursor.value?'?cursor='+encodeURIComponent(ownCircleCursor.value):''));const rows=page.items.filter(row=>row.status==='ACTIVE');ownCircles.value=more?[...ownCircles.value,...rows]:rows;ownCircleCursor.value=page.nextCursor||''}
const loadOwnCircles=()=>perform(()=>ownCirclesData(true))
async function loadManage(value:ManagedKind,more=false){manageKind.value=value;if(!more)newContent();await perform(()=>manageData(more))}
function newContent(){Object.assign(contentForm,contentDefaults());adminChapters.value=[];resetChapter()}
async function editContent(row:ManagedRow){await perform(async()=>{Object.assign(contentForm,contentDefaults(),{id:row.id,revision:Number(row.revision),title:String(row.title||row.name||''),intro:String(row.intro||''),detail:String(row.detail||''),price:String(row.price||0),stock:String(row.stock||0),validityDays:String(row.validityDays||0),persona:String(row.persona||''),needApproval:!!row.needApproval,assetIds:[...(Array.isArray(row.images)?row.images:row.cover?[row.cover]:[])].filter((path):path is string=>typeof path==='string'&&/^\/api\/v1\/lease\/assets\/[a-zA-Z0-9_-]+$/.test(path)).map(path=>path.split('/').at(-1)!)});if(manageKind.value==='course')adminChapters.value=(await managedCall<Page>('/manage/course/'+row.id+'/chapters')).items})}
async function saveContent(){await perform(async()=>{const f=contentForm,k=manageKind.value;const body=k==='product'?{title:f.title,intro:f.intro,detail:f.detail,price:Number(f.price),stock:Number(f.stock),assetIds:f.assetIds}:k==='course'?{title:f.title,intro:f.intro,price:Number(f.price),validityDays:Number(f.validityDays),assetIds:f.assetIds}:k==='circle'?{name:f.title,intro:f.intro}:{name:f.title,persona:f.persona,...(!f.id&&site.value?.templateId!=='single-agent'?{circleId:ownCircles.value[contentCircleIndex.value]?.id}:{})};const result=await managedCall<ManagedRow>('/manage/'+k+(f.id?'/'+f.id:''),f.id?'PUT':'POST',{...body,...(f.id?{revision:f.revision}:{})});f.id=result.id;f.revision=Number(result.revision);await manageData();notice.value='内容已保存，需人工审核后发布'})}
async function publishContent(active:boolean){await perform(async()=>{const k=manageKind.value,status=k==='product'?(active?'ON_SALE':'OFF_SHELF'):k==='course'?(active?'APPROVED':'DRAFT'):k==='circle'?(active?'ACTIVE':'DISABLED'):(active?'APPROVED':'DISABLED');const row=await managedCall<ManagedRow>('/manage/'+k+'/'+contentForm.id+'/review','POST',{revision:contentForm.revision,status,reason:reviewReason.value,...(k==='circle'?{needApproval:contentForm.needApproval}:{})});contentForm.revision=Number(row.revision);await manageData();notice.value=active?'审核配置已保存，内容已启用':'内容已暂停发布'})}
function resetChapter(){Object.assign(chapterForm,{id:'',title:'',content:'',sortOrder:'0',freeTrial:false})}
function editChapter(row:ManagedRow){Object.assign(chapterForm,{id:row.id,title:row.title,content:row.content,sortOrder:String(row.sortOrder),freeTrial:!!row.freeTrial})}
async function saveChapter(){await perform(async()=>{const {id,...body}=chapterForm;const result=await managedCall<ManagedRow>('/manage/course/'+contentForm.id+'/chapters','POST',{...body,sortOrder:Number(body.sortOrder),revision:contentForm.revision,...(id?{id}:{})});contentForm.revision=Number(result.revision);adminChapters.value=(await managedCall<Page>('/manage/course/'+contentForm.id+'/chapters')).items;await manageData();notice.value='章节已保存，课程需重新审核'})}
async function chooseAsset(){await perform(async()=>{const file=await new Promise<UniApp.ChooseImageSuccessCallbackResult>((done,reject)=>uni.chooseImage({count:1,sizeType:['original'],success:done,fail:()=>reject(new Error('未选择图片'))}));const bytes=await readManagedImage(file.tempFilePaths[0]);const asset=await managedCall<{id:string}>('/assets','POST',bytes);contentForm.assetIds=manageKind.value==='course'?[asset.id]:[...contentForm.assetIds,asset.id].slice(-6);notice.value='本应用图片已上传'})}
async function changePassword(){await perform(async()=>{await managedCall('/auth/password','PUT',passwordForm);clearManagedSession();context.value=undefined;passwordForm.currentPassword='';passwordForm.newPassword='';notice.value='密码已修改，请重新登录'})}
async function createExport(){await perform(async()=>{exported.value=await managedCall('/exports/paged','POST',{});notice.value='退出快照已建立，请在授权截止前保存各页'})}
async function downloadManifest(){await perform(async()=>{notice.value=await saveManagedJson('managed-manifest-'+exported.value!.id+'.json',JSON.stringify(exported.value!.manifest,null,2))})}
async function downloadPage(collection:string,page:number){await perform(async()=>{const value=await managedCall<unknown>('/exports/'+exported.value!.id+'/pages/'+collection+'/'+page,'GET',undefined,{'x-export-token':exported.value!.downloadToken});notice.value=await saveManagedJson('managed-'+collection+'-'+page+'.json',JSON.stringify(value,null,2))})}
onMounted(boot)
</script>
