px}.check{display:flex;align-items:center;gap:12px}button{font-size:15px;border-radius:5px;background:#e5ecf3;color:#21354a;padding:10px 18px;margin:10px 0;min-height:43px}button.primary{background:var(--brand);color:var(--brand-ink)}button.quiet{background:transparent;color:var(--accent-ink);padding:8px 12px;flex-shrink:0}button[disabled]{opacity:.55}.detail{background:white;padding:24px;margin:25px 0;border-left:4px solid var(--brand);border-radius:4px}.body-copy{display:block;white-space:pre-wrap;line-height:1.9;overflow-wrap:anywhere;margin:14px 0;max-width:72ch}.row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid #c2d0dc;overflow-wrap:anywhere}.row button{flex-shrink:0}.record,.post,.message{padding:23px 0;border-bottom:1px solid #c2d0dc}.speaker{display:block;font-size:13px;font-weight:700;color:var(--accent-ink);margin-top:12px}.empty{display:block;padding:45px 0;color:#52687d;line-height:1.8}.feedback{padding:15px 18px;margin-top:20px;background:#e5f0f2;border-radius:4px;line-height:1.7}.feedback.error{background:#fff1ef;color:#ad392b}.footer{display:flex;justify-content:space-between;gap:20px;font-size:12px;color:#52687d;border-top:1px solid #c2d0dc;margin-top:70px;padding-top:22px;line-height:1.8}.status{font-size:12px;color:#ad392b;line-height:1.8;margin-top:25px}.reading{margin:24px 0;padding-top:18px}
@media(max-width:700px){.shell{padding:24px 18px}.brand-name{font-size:27px}.workspace{display:block;margin-top:20px}.rail{flex-direction:row;overflow-x:auto;align-items:center;margin-bottom:25px}.rail .account,.rail .status{display:none}.rail button{white-space:nowrap;flex-shrink:0;font-size:14px}.heading{font-size:25px}.detail{padding:18px}.entry{margin:42px auto}.row{flex-wrap:wrap}.row>text{max-width:100%}.footer{flex-direction:column;gap:8px}.resource .cover{width:68px;height:68px}.resource{gap:14px}.section-head{gap:8px}.title{font-size:18px}}
